INSERT INTO `fertilizer` VALUES (1,'Сечовина (Карбамід)','Перед посадкою, на ранніх етапах росту','Азотне','Високий вміст азоту (46%). Сприяє швидкому росту зеленої маси.'),(2,'Аміачна селітра','На початку вегетації','Азотне','Містить 34% азоту. Швидко засвоюється рослинами, стимулює ріст і зелений покрив.'),(3,'Сульфат амонію','Перед посадкою, в період росту','Азотне','Містить азот і сірку. Підвищує стійкість рослин до захворювань.'),(4,'Нітрат кальцію (Кальцієва селітра)','Перед зав\'яззю плодів','Азотне','Запобігає утворенню гнилі плодів, зміцнює клітинні стінки.'),(5,'Карбонат амонію','Перед посадкою','Азотне','Швидкодіюче добриво, яке легко засвоюється рослинами.'),(6,'Хлористий калій','Перед посадкою, під час росту','Калійне','Високий вміст калію (60%). Сприяє підвищенню стійкості до посухи та покращенню смакових якостей плодів.'),(7,'Сульфат калію','Під час формування плодів','Калійне','Не містить хлору, підходить для чутливих рослин (кавунів, динь). Покращує якість і солодкість плодів.'),(8,'Калійна сіль','Перед посадкою, в період росту','Калійне','Джерело калію, підвищує врожайність, але містить хлор, що обмежує застосування на деяких культурах.'),(9,'Монокалійфосфат (MKP)','Під час цвітіння','Калійно-фосфорне','Покращує цвітіння та утворення зав\'язей.'),(10,'Зола деревна','Перед посадкою, як мульча','Органічне','Містить калій і фосфор. Покращує структуру ґрунту, нейтралізує кислотність.'),(11,'Суперфосфат','Перед посадкою, під час цвітіння','Фосфорне','Містить фосфор, кальцій і сірку. Покращує розвиток кореневої системи.'),(12,'Потрійний суперфосфат','Перед посадкою','Фосфорне','Високий вміст фосфору (до 46%). Підходить для підживлення овочів та динь.'),(13,'Фосфоритне борошно','Перед посадкою','Фосфорне','Повільно діюче добриво. Ефективне на кислих ґрунтах, сприяє розвитку кореневої системи.'),(14,'Амофос','Перед посівом, під час росту','Фосфорно-азотне','Містить азот і фосфор. Сприяє розвитку коріння та підвищенню врожайності.'),(15,'Органічний перегній','Перед посадкою','Органічне','Забезпечує ґрунт необхідними мікроелементами та покращує його структуру.'),(16,'Компост','Перед висадкою','Органічне','Підвищує родючість ґрунту, містить необхідні макро- і мікроелементи.'),(17,'Борне добриво','Перед цвітінням','Мікродобриво','Покращує цвітіння та зав\'язування плодів, важливе для кавунів і динь.'),(18,'Комплексне NPK добриво','Перед посадкою, під час росту','Комплексне','Містить азот, фосфор і калій, забезпечує повноцінне живлення рослин.'),(19,'Сульфат магнію','Під час активного росту','Мінеральне','Містить магній і сірку, забезпечує кращий фотосинтез та запобігає хлорозу.');
/*!40000 ALTER TABLE `fertilizer` ENABLE KEYS */;
