INSERT INTO `sorts` VALUES (1,'Морква Паризький ринок','Оранжевий','70 - 75 днів ','30-50 г','Сорт використовується як для консервування, так і для вживання у свіжому вигляді.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/morkov-parijskiy-rynok-semena2.jpg?1734963120','Плоди відрізняються своєю незвичайною округлою формою і маленькими розмірами (2-4 см в діаметрі). М\'якоть яскраво-помаранчева, шкірка тонка і практично непомітна.',1),(2,'Морква амстердамська','Оранжевий','75 - 85 днів ','100-200 г','Сорт використовується для вживання у свіжому вигляді','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/morkov-stolovaya-amsterdamskaya-semena_1.jpg?1734963840','серцевина маленька, м\'якоть ніжна, соковита',1),(3,'Морква Нантес Скарлет','Оранжевий','70 - 80 днів','80-120 г','Сорт використовується для вживання у свіжому вигляді','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/morkov-nantes-skarlet_1.jpg?1734964200','Плоди моркви виростають довжиною до 18 см. Для них властивий гарний помаранчевий колір і відмінний товарний вигляд. Сорт високоврожайний і стійкий до утворення стрілок',1),(4,'Морква Абако F1','Оранжевий','80 - 85 днів ','100-225 г','Сорт придатний для комерційного виробництва, тривалого зберігання, переробки на дитячі соки, пюре.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/morkov-abako-f1_1.jpg?1734964560','Плоди виростають помірно великі до 16 см, забарвлення м\'якоті темно-помаранчева, внутрішня частина - з червонуватим відтінком через високий вміст каротину',1),(5,'Морква Артек','помаранчево-червоний','65 - 85 днів ','80 - 130 г','Сорт використовується для вживання у свіжому вигляді','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/morkov-artek_1.jpg?1734964560','Плоди цього сорту відрізняються соковитістю і відмінним смаком.',1),(6,'Морква оленка','Оранжевий','85 - 100 днів ','80 - 110 г','Сорт використовується для вживання у свіжому вигляді','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/morkov-alenka_1.jpg?1734964920','Відрізняється високою врожайністю і стійкістю до хвороб і низьких температур. Серединка у плодів виражена слабко.',1),(7,'Морква каріні','Оранжевий','90 - 100 днів ','100 - 150 г','Рекомендовані для вживання у свіжому вигляді, приготування дієтичного та дитячого харчування, віджимання соку, а також інших видів кулінарної переробки.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/morkov-karini_1.jpg?1734964920','Коренеплоди насичено-помаранчеві, циліндричні, тупоносі, соковиті і солодкі.',1),(8,'Морква лагуна F1','Оранжевий','80 - 85 днів ','100 - 130 г','Використовують вживання в свіжому вигляді, переробки, консервування та заморозки. ','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/morkov-laguna-f1_1.jpg?1734964920','Коренеплоди довжиною 17 - 20 см. Форма циліндрична, рівна, витягнута. Колір м\'якоті: інтенсивно-оранжевий. Серцевина дуже маленька.',1),(9,'Морква сімейний сад F1','Оранжевий','80 - 90 днів ','100 - 200 г','Можна вирощувати як в комерційних цілях, так і для домашнього вжитку. Підходить для вживання дітям - у свіжому вигляді й у якості соків або пюре.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/morkov-semeynyy-sad-f1_1.jpg?1734965280','Плоди середні - довжиною до 16 см. Серединка помаранчево-червона, що свідчить про високий вміст каротину.',1),(10,'Берлікумер','Оранжевий','110 - 130 днів ','120 - 190 г','Використовують вживання в свіжому вигляді, переробки, консервування та заморозки. ','https://images.prom.ua/4135985376_nasinnya-morkvi-berlikumer.jpg','Коренеплід довгий, циліндричний з тупим кінчиком. Серцевина помаранчева. Придатний для тривалого зберігання. При зберіганні вміст каротину збільшується у 1,5 разу. Культура вимоглива до вологи та родючих пухких ґрунтів. Висівати у вологий ґрунт на глибину 2-3 см.',2),(11,'Морква вітамінна 6','Оранжевий','100 - 120 днів ','60 - 160 г','Рекомендований для вживання у свіжому вигляді та для зимового зберігання.','https://images.prom.ua/4134542814_nasinnya-morkvi-vitaminna.jpg','Коренеплід помаранчевий, циліндричний, тупокінцевий, довжиною 15 см, майже повністю занурений у ґрунт. М\'якуш оранжево червоний, соковитий, солодкий. Вимагає зрошення та розпушування ґрунту. Культура вимоглива до вологи та родючих, пухких ґрунтів. Смакові якості коренеплодів добрі.   Висівати у вологий ґрунт на глибину 2-3 см.',2),(12,'Морква каротель','оранжево-червоний','83 - 105 днів ','80 г','Цей сорт рекомендується для споживання у свіжому вигляді, а також для переробки в соки та пюре.','https://images.prom.ua/4139867104_nasinnya-morkvi-karotel.jpg','Коренеплід довжиною 10-12 см, насичено оранжево-червоного кольору, тупокінцевий. М\'якуш соковитий, дуже солодкий, хрумкий. Серед середньоранніх сортів відрізняється лежкістю коренеплодів та збереженням у них вітамінів. Висівати у вологий ґрунт на глибину 2-3 см.',2),(13,'Морква ласуня','червоно-жовтогарячий','80 - 104 днів ','60 - 155 г','Призначений для використання у свіжому вигляді, переробки, зберігання.','https://images.prom.ua/4164461134_nasinnya-morkvi-lasunya.jpg','Коренеплід циліндричний, інтенсивного червоно-жовтогарячого кольору, соковита, солодка, довжиною 20 см.  Культура вимоглива до вологи та родючих пухких ґрунтів. Для отримання дружних сходів насіння рекомендується змочувати у воді кімнатної температури на добу, потім просушувати при температурі 15-16°С до сипучості. Висівати у вологий ґрунт на глибину 2-3 см.',2),(14,'Морква лосиноострівська','червоно-жовтогарячий','100 - 110 днів ','70 - 150 г','Сорт використовується для вживання у свіжому вигляді','https://images.prom.ua/4164472132_nasinnya-morkvi-losinoostrivska.jpg','Коренеплід циліндричний, інтенсивного червоно-жовтогарячого кольору, соковита, солодка, довжиною 15-25см. Один із найкращих столових сортів. Культура вимоглива до вологи та родючих пухких ґрунтів. Для отримання дружних сходів насіння рекомендується змочувати у воді кімнатної температури на добу, потім просушувати при температурі 